fun mod(num: Long): Long {
    return when {
        num >= MOD -> num % MOD
        num < 0 -> (num % MOD + MOD) % MOD
        else -> num
    }
}

fun mul(vararg args: Long): Long {
    if (args.isEmpty()) throw IllegalArgumentException("参数不能为空")
    if (args.size == 1) return args[0]
    var result = args[0]
    for (i in 1 until args.size) {
        val a = result
        val b = args[i]
        result = ( (a / 65536) * b % MOD * 65536 + (a and 65535) * b ) % MOD
    }
    return result
}

fun getPrimes(n: Int): BooleanArray {
