        for (p in primes) {
            val prod = p * i
            if (prod > n) break
            nums[prod] = false
            if (i % p == 0) break
        }
    }
    return nums
}

fun solve(read: () -> String): Long {
    val rns = { read().split("\\s+").map { it.toLong() } }
    val (n, m) = rns().let { (it[0].toInt(), it[1]) }

