    val inputs = reader.readText().split("\n").filter { it.isNotBlank() }
    var index = 0
    val read = { inputs[index++].trim() }

    val t = 1
    val results = mutableListOf<Long>()
    for (i in 0 until t) {
        results.add(solve(read))
    }
    println(results.joinToString("\n"))
}

